"use client";

import { useId, useRef, type HTMLAttributes, type ReactNode } from "react";

export function Popover({ trigger, children, className = "" }: { trigger: ReactNode; children: ReactNode; className?: string }) { const ref = useRef<HTMLDivElement>(null); const id = useId(); return <span className={`co-relative co-inline-block ${className}`.trim()}><button type="button" aria-haspopup="dialog" aria-controls={id} onClick={() => ref.current?.togglePopover()}>{trigger}</button><div ref={ref} id={id} popover="auto" className="co-m-0 co-w-72 co-rounded-lg co-border co-border-black/15 co-bg-white co-p-4 co-shadow-lg">{children}</div></span>; }
export function PopoverContent(props: HTMLAttributes<HTMLDivElement>) { return <div {...props} />; }
